<?php
require "db.php";
$q = trim((string)($_GET["q"] ?? ""));
$stmt = $conn->prepare("SELECT f.id, f.name, f.phone, f.address, COUNT(b.id) AS bill_count, COALESCE(SUM(b.total_amount),0) AS total_value FROM farmers f LEFT JOIN bills b ON b.farmer_id=f.id WHERE f.name LIKE CONCAT('%',?,'%') OR f.phone LIKE CONCAT('%',?,'%') GROUP BY f.id, f.name, f.phone, f.address ORDER BY f.id DESC");
$stmt->bind_param("ss",$q,$q); $stmt->execute(); $rows=$stmt->get_result();
?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>JM PADDY | Farmers</title><link rel="stylesheet" href="style.css"></head><body><div class="app"><aside class="sidebar"><h2>🌾 JM PADDY</h2><p class="subtitle">Paddy Billing System</p><nav><a href="dashboard.php">🏠 Dashboard</a><a href="bill.php">🧾 Create Bill</a><a class="active" href="farmers.php">👨‍🌾 Farmers</a><a href="history.php">📋 Bill History</a><a href="reports.php">📈 Reports</a><a href="prices.php">💰 Price Management</a><a href="settings.php">⚙️ Settings</a></nav></aside><main class="main"><header class="topbar"><div><h1>Farmers</h1><p>Farmer directory based on saved billing records.</p></div><a class="btn" href="bill.php">＋ Add via New Bill</a></header><section class="panel"><form method="get" class="grid" style="margin-bottom:18px"><div><label for="q">Search farmer name or phone</label><input id="q" name="q" value="<?= htmlspecialchars($q) ?>" placeholder="Type a name or phone"></div><div style="align-self:end"><button class="btn" type="submit">Search</button> <a class="btn" style="background:#718078" href="farmers.php">Clear</a></div></form><div style="overflow-x:auto"><table><thead><tr><th>Farmer</th><th>Phone</th><th>Address</th><th>Bills</th><th>Total Bill Value</th></tr></thead><tbody><?php if($rows && $rows->num_rows): while($r=$rows->fetch_assoc()): ?><tr><td><?= htmlspecialchars($r["name"]) ?></td><td><?= htmlspecialchars($r["phone"] ?: "—") ?></td><td><?= htmlspecialchars($r["address"] ?: "—") ?></td><td><?= (int)$r["bill_count"] ?></td><td>Rs. <?= number_format((float)$r["total_value"],2) ?></td></tr><?php endwhile; else: ?><tr><td colspan="5">No matching farmer records found.</td></tr><?php endif; ?></tbody></table></div><p>Note: farmer records are created when a bill is saved. Editing and deleting farmer records is not enabled yet.</p></section></main></div></body></html>